; Divina - "High Tension... Never Born" (1990)
; Relocatable rebuild of the image that the original cruncher unpacked
; at $4FFF0 (entry $7C800).
; - no ORG: every absolute address is a label
; - the bitplane pointers in the copper list are filled at runtime by
;   FixCopper, called from the first bytes of the image (padding in the
;   original, so all the other offsets are unchanged)
; - self-modifying code kept (song speed at mt_music+9, JMP to the old
;   level 3 vector at JmpOldInt): the target is a plain 68000
; - stability fixes (marked "fix:"), needed on A600/KS 2.05:
;   * Level3Int saves and restores every register (the original saved none
;     and trashed D0-D4/A0-A6 of whatever code it interrupted)
;   * Level3Int runs the frame code only for VERTB, other level 3 sources
;     go straight to the system handler
;   * DMACON written with word moves (byte/long writes hit the wrong bits
;     or the wrong register)
;   * OpenLibrary with version 0, CloseLibrary on exit

EXT_0000	EQU	$0
EXT_0001	EQU	$4
AUTO_INT3	EQU	$6C
EXT_0003	EQU	$BFE001
EXT_0004	EQU	$DFF006
EXT_DFF01F	EQU	$DFF01F		; INTREQR, low byte
EXT_0005	EQU	$DFF040
EXT_0006	EQU	$DFF042
EXT_0007	EQU	$DFF044
EXT_0008	EQU	$DFF048
EXT_0009	EQU	$DFF050
EXT_000a	EQU	$DFF054
