EXT_000f	EQU	$DFF096
EXT_0010	EQU	$DFF0A0
EXT_0011	EQU	$DFF0A4
EXT_0012	EQU	$DFF0A8
EXT_0013	EQU	$DFF0B0
EXT_0014	EQU	$DFF0B4
EXT_0015	EQU	$DFF0B8
EXT_0016	EQU	$DFF0C0
EXT_0017	EQU	$DFF0C4
EXT_0018	EQU	$DFF0C8
EXT_0019	EQU	$DFF0D0
EXT_001a	EQU	$DFF0D4
EXT_001b	EQU	$DFF0D8





	SECTION	divina,CODE_C	; chip RAM: copper, bitplanes, samples

SECSTRT_0:
	JSR	FixCopper		; fill bitplane pointers
	JMP	Main			;4fff0: 4ef90007c800
	DS.W	2			;4fffc
