; Fill the high/low words of the bitplane pointers in the copper list
FixCopper:
	LEA	CopPtrTab(PC),A0
.loop:	MOVE.L	(A0)+,D0
	BEQ.S	.done
	MOVEA.L	D0,A1
	MOVE.L	(A0)+,D0
	MOVE.W	D0,6(A1)
	SWAP	D0
	MOVE.W	D0,2(A1)
	BRA.S	.loop
.done:	RTS

CopPtrTab:
	DC.L	CopBpl1,Picture
	DC.L	CopBpl2,Picture+$2800
	DC.L	CopBpl3,Picture+$5000
	DC.L	CopBpl4,Picture+$7800
	DC.L	CopBpl5,Picture+$a000
	DC.L	CopScrBpl,ScrollBuf
	DC.L	0

	END
